// Pokemon against values from Essentials' own Ruby code (rubyReference.json,
// generated by running 014_Pokemon + this game's plugin patches on the
// harness-compiled PBS data), plus save round-trips.
import { beforeAll, describe, expect, it } from "vitest";
import { seedRandom } from "../../core/random";
import { GameData } from "../../data/gameData";
import { loadGameDataForTests } from "../../data/gameData/testing";
import { G } from "../globals";
import { Pokemon } from "./Pokemon";
import { PokemonOwner } from "./PokemonOwner";
import ref from "./rubyReference.json";

beforeAll(() => {
  loadGameDataForTests();
  seedRandom(1);
  G.player = null;
});

const statsOf = (p: Pokemon) => ({ totalhp: p.totalhp, attack: p.attack, defense: p.defense, spatk: p.spatk, spdef: p.spdef, speed: p.speed });

describe("Pokemon", () => {
  it("calculates stats like Ruby", () => {
    for (const c of ref.stats) {
      const p = new Pokemon(c.species, c.level, null);
      for (const s of GameData.Stat.eachMain()) {
        p.iv[s.id] = c.iv;
        p.ev[s.id] = c.ev;
      }
      p.nature = c.nature;
      p.calcStats();
      expect(p.formSimple, c.species).toBe(c.form);
      expect(statsOf(p), `${c.species} Lv.${c.level}`).toEqual({
        totalhp: c.totalhp, attack: c.attack, defense: c.defense, spatk: c.spatk, spdef: c.spdef, speed: c.speed,
      });
    }
  });

  it("derives nature, gender, ability and shininess from the personal ID like Ruby", () => {
    for (const c of ref.personal) {
      const p = new Pokemon("RALTS", 10, new PokemonOwner(0x12345678, "Gold", 0, 2));
      p.personalID = c.pid;
      // Clear the lazily computed values, as the Ruby reference does.
      const json = p.toJSON();
      Object.assign(json, { nature: null, gender: null, abilityIndex: null, ability: null, shiny: null, superShiny: null });
      const q = Pokemon.fromJSON(json);
      expect(q.nature!.id, `pid ${c.pid}`).toBe(c.nature);
      expect(q.gender, `pid ${c.pid}`).toBe(c.gender);
      expect(q.abilityIndex).toBe(c.abilityIndex);
      expect(q.abilityId).toBe(c.ability);
      expect(q.shiny).toBe(c.shiny);
      expect(q.superShiny).toBe(c.superShiny);
    }
  });

  it("checks evolutions like Ruby", () => {
    const mk = (sp: string, lv: number) => new Pokemon(sp, lv, null);
    const got: [string, string | null][] = [];
    let p = mk("CHARMANDER", 16); got.push(["CHARMANDER lv16 levelup", p.checkEvolutionOnLevelUp()]);
    p = mk("CHARMANDER", 15); got.push(["CHARMANDER lv15 levelup", p.checkEvolutionOnLevelUp()]);
    p = mk("PIKACHU", 10); got.push(["PIKACHU thunderstone", p.checkEvolutionOnUseItem("THUNDERSTONE")]);
    p = mk("PIKACHU", 10); got.push(["PIKACHU firestone", p.checkEvolutionOnUseItem("FIRESTONE")]);
    p = mk("ONIX", 10); p.item = "METALCOAT"; const other = mk("RATTATA", 5); got.push(["ONIX metalcoat trade", p.checkEvolutionOnTrade(other)]);
    p = mk("ONIX", 10); got.push(["ONIX trade", p.checkEvolutionOnTrade(other)]);
    p = mk("TYROGUE", 20);
    for (const s of GameData.Stat.eachMain()) { p.iv[s.id] = 31; p.ev[s.id] = 0; }
    p.nature = "ADAMANT";
    p.calcStats();
    got.push(["TYROGUE lv20 adamant", p.checkEvolutionOnLevelUp()]);
    p.nature = "BOLD";
    got.push(["TYROGUE lv20 bold", p.checkEvolutionOnLevelUp()]);
    p = mk("CHARMANDER", 16); p.item = "EVERSTONE"; got.push(["CHARMANDER everstone", p.checkEvolutionOnLevelUp()]);
    p = mk("GOLBAT", 30); p.happiness = 220; got.push(["GOLBAT happiness 220", p.checkEvolutionOnLevelUp()]);
    p = mk("GOLBAT", 30); p.happiness = 150; got.push(["GOLBAT happiness 150", p.checkEvolutionOnLevelUp()]);
    expect(got).toEqual(ref.evolution);
  });

  it("learns its last four level-up moves like Ruby", () => {
    for (const [sp, lv, moves] of ref.moves as [string, number, [string, number][]][]) {
      const p = new Pokemon(sp, lv, null);
      expect(p.moves.map((m) => [m.id, m.pp]), sp).toEqual(moves);
    }
  });

  it("levels, exp and HP", () => {
    const p = new Pokemon("BULBASAUR", 10, null);
    expect(p.level).toBe(10);
    expect(p.exp).toBe(GameData.GrowthRate.get("Parabolic").minimumExpForLevel(10));
    expect(p.hp).toBe(p.totalhp);
    p.exp = p.growthRate().minimumExpForLevel(12) + 1;
    expect(p.level).toBe(12);
    p.hp = -5;
    expect(p.hp).toBe(0);
    expect(p.fainted()).toBe(true);
    p.heal();
    expect(p.hp).toBe(p.totalhp);
    expect(() => { p.level = 0; }).toThrow();
  });

  it("moves, ribbons, items and Pokérus", () => {
    const p = new Pokemon("PIKACHU", 50, null);
    p.learnMove("TACKLE");
    expect(p.moves.map((m) => m.id)).toEqual(["THUNDERBOLT", "LIGHTSCREEN", "THUNDER", "TACKLE"]);
    p.learnMove("THUNDERBOLT"); // known: moved to the end
    expect(p.moves.map((m) => m.id)).toEqual(["LIGHTSCREEN", "THUNDER", "TACKLE", "THUNDERBOLT"]);
    p.forgetMove("TACKLE");
    expect(p.numMoves()).toBe(3);
    p.moves[0]!.ppup = 3;
    expect(p.moves[0]!.totalPp).toBe(30 + Math.floor((30 * 3) / 5));
    p.item = "LIGHTBALL";
    expect(p.hasItem()).toBe(true);
    expect(p.hasItem("LIGHTBALL")).toBe(true);
    p.item = "NOTANITEM"; // ignored, as in Ruby
    expect(p.itemId).toBe("LIGHTBALL");
    p.giveRibbon("HOENNCOOL");
    expect(p.hasRibbon("HOENNCOOL")).toBe(true);
    p.givePokerus(3);
    expect(p.pokerusStage()).toBe(1);
    expect(p.pokerusStrain()).toBe(3);
    p.curePokerus();
    expect(p.pokerusStage()).toBe(2);
  });

  it("happiness changes (with the soft cap) and its Ruby clamp error above 179", () => {
    const p = new Pokemon("PIKACHU", 50, null);
    p.happiness = 100;
    p.changeHappiness("walking");
    expect(p.happiness).toBe(102);
    p.happiness = 178;
    p.changeHappiness("levelup");
    expect(p.happiness).toBe(179);
    p.happiness = 200;
    expect(() => p.changeHappiness("walking")).toThrow(RangeError);
    p.changeHappiness("evberry");
    expect(p.happiness).toBe(202);
  });

  it("forms: species with a getForm handler and form-specific data", () => {
    const giratina = new Pokemon("GIRATINA", 50, null);
    expect(giratina.form).toBe(0);
    giratina.item = "GRISEOUSORB";
    expect(giratina.form).toBe(1);
    expect(giratina.speciesData().id).toBe("GIRATINA_1");
    const unown = new Pokemon("UNOWN", 5, null);
    expect(unown.formSimple).toBeGreaterThanOrEqual(0);
    expect(unown.formSimple).toBeLessThan(28);
  });

  it("shadow Pokémon, mega forms and ZUD flags", () => {
    const p = new Pokemon("CHARIZARD", 50, null);
    expect(p.dynamaxAble).toBe(true);
    expect(p.hasGmax()).toBe(true);
    p.dynamaxLvl = 15;
    expect(p.dynamaxLvl).toBe(10);
    p.gmaxFactor = true;
    expect(p.canGmax()).toBe(true);
    const hp = p.totalhp;
    p.dynamax = true;
    p.calcStats();
    expect(p.totalhp).toBe(Math.ceil(hp * 2.0));
    p.unmax();
    expect(p.totalhp).toBe(hp);
    p.item = "CHARIZARDITEX";
    expect(p.hasMegaForm()).toBe(true);
    const s = new Pokemon("TOGEPI", 20, null);
    s.makeShadow();
    expect(s.shadowPokemon()).toBe(true);
    expect(s.heartStage()).toBe(5);
    expect(s.moves.length).toBeGreaterThan(0);
  });

  it("round-trips through JSON exactly", () => {
    const p = new Pokemon("EEVEE", 25, new PokemonOwner(123456, "Gold", 0, 2));
    p.name = "Vee";
    p.item = "LEFTOVERS";
    p.giveRibbon("HOENNCOOL");
    p.ivMaxed.SPEED = true;
    p.makeShadow();
    p.adjustHeart(-100);
    p.dynamaxLvl = 3;
    p.setEvoMoveCount("TACKLE", 4);
    p.shinyLeaf = 2;
    p.amieAffection = 40;
    p.fused = new Pokemon("PIKACHU", 5, null);
    const json = JSON.parse(JSON.stringify(p.toJSON())) as ReturnType<Pokemon["toJSON"]>;
    const q = Pokemon.fromJSON(json);
    expect(q).toBeInstanceOf(Pokemon);
    expect(JSON.parse(JSON.stringify(q.toJSON()))).toEqual(json);
    expect(q.name).toBe("Vee");
    expect(q.moves[0]).toBeInstanceOf(Pokemon.Move);
    expect(q.owner).toBeInstanceOf(PokemonOwner);
    expect(q.fused).toBeInstanceOf(Pokemon);
    expect(statsOf(q)).toEqual(statsOf(p));
    const c = p.clone();
    expect(c).not.toBe(p);
    expect(c.toJSON()).toEqual(p.toJSON());
    c.iv.HP = 0;
    expect(p.iv.HP).not.toBe(0);
  });
});
